  spec constant jsonb:=$evidence_projection_proof_spec${"target":{"oid":"30039","sha":"ea231988a9911232814ef6bd59261d1810dc25a34fe03ce74cbea71f47ff8216","metadata":{"oid":"30039","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"14","proname":"offering_document_evidence_summary","prorows":0,"pronargs":1,"proowner":"16388","proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["target_revision"],"proargtypes":["2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":"22414","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},"dependencies":[{"oid":"25750","sha":"3af34c6fb9b6e51b37d6fdfbf25193f5c079d430f002a5d02186444ee917fe1e","metadata":{"oid":"25750","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13619","proname":"offering_package_projection_pre_appointment","prorows":0,"pronargs":2,"proowner":"16388","proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["c","target_product"],"proargtypes":["3802","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"24138","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"oid":"25751","sha":"4b2cf0aac6c0ea150dccabffb2959dd5b79610720389f04638875ca028bf4f8c","metadata":{"oid":"25751","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"14","proname":"offering_history_projection","prorows":0,"pronargs":1,"proowner":"16388","proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["target_product"],"proargtypes":["2950"],"proisstrict":fal