,"indisvalid":true,"indisunique":true,"indnkeyatts":2,"indcheckxmin":false,"indcollation":["0","0"],"indimmediate":true,"indisprimary":false,"indisclustered":false,"indisexclusion":false,"indisreplident":false,"indnullsnotdistinct":false},{"indkey":[1],"indpred":null,"indclass":["10065"],"indexprs":null,"indnatts":1,"indrelid":"29947","indislive":true,"indoption":[0],"indexrelid":"29957","indisready":true,"indisvalid":true,"indisunique":true,"indnkeyatts":1,"indcheckxmin":false,"indcollation":["0"],"indimmediate":true,"indisprimary":true,"indisclustered":false,"indisexclusion":false,"indisreplident":false,"indnullsnotdistinct":false},{"indkey":[2],"indpred":null,"indclass":["10065"],"indexprs":null,"indnatts":1,"indrelid":"29947","indislive":true,"indoption":[0],"indexrelid":"29959","indisready":true,"indisvalid":true,"indisunique":true,"indnkeyatts":1,"indcheckxmin":false,"indcollation":["0"],"indimmediate":true,"indisprimary":false,"indisclustered":false,"indisexclusion":false,"indisreplident":false,"indnullsnotdistinct":false}],"constraints":[{"oid":"29737","conbin":null,"conkey":[1],"confkey":null,"conname":"offering_document_profiles_pkey","contype":"p","conindid":"29736","conrelid":"29727","contypid":"0","conexclop":null,"conffeqop":null,"confrelid":"0","conpfeqop":null,"conppeqop":null,"conislocal":true,"condeferred":false,"confdeltype":" ","confupdtype":" ","coninhcount":0,"conparentid":"0","connamespace":"22414","connoinherit":true,"convalidated":true,"condeferrable":false,"confmatchtype":" ","confdelsetcols":null},{"oid":"29739","conbin":null,"conkey":[2,1],"confkey":null,"conname":"offering_document_profiles_product_id_offering_revision_id_key","contype":"u","conindid":"29738","conrelid":"29727","contypid":"0","conexclop":null,"conffeqop":null,"confrelid":"0","conpfeqop":null,"conppeqop":null,"conislocal":true,"condeferred":false,"confdeltype":" ","confupdtype":" ","coninhcount":0,"conparentid":"0","connamespace":"22414","connoinherit":true,"convalidated":true,"condeferrable":false,"confmatchtype":" ","confdelsetcols":null},{"oid":"29958","conbin":null,"conkey":[1],"confkey":null,"conname":"offering_document_manifests_pkey","contype":"p","conindid":"29957","conrelid":"29947","contypid":"0","conexclop":null,"conffeqop":null,"confrelid":"0","conpfeqop":null,"conppeqop":null,"conislocal":true,"condeferred":false,"confdeltype":" ","confupdtype":" ","coninhcount":0,"conparentid":"0","connamespace":"22414","connoinherit":true,"convalidated":true,"condeferrable":false,"confmatchtype":" ","confdelsetcols":null},{"oid":"29960","conbin":null,"conkey":[2],"confkey":null,"conname":"offering_document_manifests_offering_revision_id_key","contype":"u","conindid":"29959","conrelid":"29947","contypid":"0","conexclop":null,"conffeqop":null,"confrelid":"0","conpfeqop":null,"conppeqop":null,"conislocal":true,"condeferred":false,"confdeltype":" ","confupdtype":" ","coninhcount":0,"conparentid":"0","connamespace":"22414","connoinherit":true,"convalidated":true,"condeferrable":false,"confmatchtype":" ","confdelsetcols":null}]},"cuts":[{"name":"status","from":"when exists(select 1 from bx1_private.offering_signature_operations op join bx1_private.offering_signature_authorisations au on au.id=op.authorisation_id\n        where au.revision_id=target_revision and bx1_private.offering_signature_evidence_current(op.id)) then 'EVIDENCE_RETAINED'","to":"when coalesce((select retained.evidence_retained from retained_evidence retained),false) then 'EVIDENCE_RETAINED'","count":1},{"name":"approval","from":"'approval_allowed',exists(select 1 from bx1_private.offering_signature_operations op\n      join bx1_private.offering_signature_authorisations au on au.id=op.authorisation_id\n      where au.revision_id=target_revision and bx1_private.offering_signature_evidence_current(op.id))","to":"'approval_allowed',coalesce((select retained.evidence_retained from retained_evidence retained),false)","count":1},{"name":"profile_gate","from":"\n  select case","to":"\n  with retained_evidence as materialized (\n    select exists(select 1 from bx1_private.offering_signature_operations op join bx1_private.offering_signature_authorisations au on au.id=op.authorisation_id\n        where au.revision_id=target_revision and bx1_private.offering_signature_evidence_current(op.id)) as evidence_retained\n    from bx1_private.offering_document_profiles evidence_profile\n    where evidence_profile.offering_revision_id=target_revision\n  )\n  select case","count":1}],"retainedStatus":"exists(select 1 from bx1_private.offering_signature_operations op join bx1_private.offering_signature_authorisations au on au.id=op.authorisation_id\n        where au.revision_id=target_revision and bx1_private.offering_signature_evidence_current(op.id))","retainedApproval":"exists(select 1 from bx1_private.offering_signature_operations op\n      join bx1_private.offering_signature_authorisations au on au.id=op.authorisation_id\n      where au.revision_id=target_revision and bx1_private.offering_signature_evidence_current(op.id))","shared":"coalesce((select retained.evidence_retained from retained_evidence retained),false)","finalFence":"coalesce(bx1_portal.offering_workflow_package_projection(c,(value->>'id')::uuid),'null'::jsonb)\n          is distinct from value->'offering_package'","substitutions":[{"from":"exists(select 1 from bx1_private.offering_signature_operations op join bx1_private.offering_signature_authorisations au on au.id=op.authorisation_id\n        where au.revision_id=target_revision and bx1_private.offering_signature_evidence_current(op.id))","to":"exists(select 1 from inputs where inputs.retained_current is true)"},{"from":"exists(select 1 from bx1_private.offering_signature_operations op\n      join bx1_private.offering_signature_authorisations au on au.id=op.authorisation_id\n      where au.revision_id=target_revision and bx1_private.offering_signature_evidence_current(op.id))","to":"exists(select 1 from inputs where inputs.retained_current is true)"},{"from":"exists(select 1 from bx1_private.offering_signature_operations op join bx1_private.offering_signature_authorisations au on au.id=op.authorisation_id\n        where au.revision_id=target_revision and op.state='RECOVERY_REQUIRED')","to":"exists(select 1 from inputs where inputs.recovery_exists is true)"},{"from":"exists(select 1 from bx1_private.offering_signature_operations op join bx1_private.offering_signature_authorisations au on au.id=op.authorisation_id\n        where au.revision_id=target_revision and (op.noncurrent_reason is not null or not bx1_private.offering_signature_authorisation_current(au.id)))","to":"exists(select 1 from inputs where inputs.noncurrent_exists is true)"},{"from":"exists(select 1 from bx1_private.offering_signature_operations op join bx1_private.offering_signature_authorisations au on au.id=op.authorisation_id\n        where au.revision_id=target_revision)","to":"exists(select 1 from inputs where inputs.pending_exists is true)"},{"from":"exists(select 1 from bx1_private.offering_signature_authorisations au where au.revision_id=target_revision\n        and bx1_private.offering_signature_authorisation_current(au.id))","to":"exists(select 1 from inputs where inputs.purpose_exists is true)"},{"from":"bx1_private.offering_signature_admitted()","to":"(select inputs.admitted_current from inputs)"}]}$evidence_projection_proof_spec$::jsonb;
  metadata jsonb; dependency jsonb; actual_relations jsonb; cut jsonb; substitution jsonb;
  installed text; original text; rebuilt text; old_status text; new_status text; old_approval text; new_approval text;
  materialized_sql text; proof_query text; fresh_fence text; reader_body text;
  profile_present boolean; admitted_current boolean; retained_current boolean; flags integer;
  old_result jsonb; new_result jsonb; gated_rows bigint; cases integer:=0; changed boolean; phase_case jsonb;
  claims_before text:=pg_catalog.current_setting('request.jwt.claims',true);
  sub_before text:=pg_catalog.current_setting('request.jwt.claim.sub',true);
begin
  if current_user<>'postgres' or session_user<>'postgres' or auth.uid() is not null
    or bx1_private.test_roleplay_environment() is not true then
    raise exception 'evidence_projection_proof_owner_without_claims_required' using errcode='42501';end if;
  select to_jsonb(p) into metadata from pg_catalog.pg_proc p where p.oid=(spec->'target'->>'oid')::oid;
  installed:=metadata->>'prosrc'; original:=installed;
  if metadata is null or metadata-'prosrc' is distinct from spec->'target'->'metadata' then
    raise exception 'evidence_projection_proof_target_metadata_changed';end if;
  for cut in select value from jsonb_array_elements(spec->'cuts') with ordinality item(value,position) order by position desc loop
    if (length(original)-length(replace(original,cut->>'to','')))/length(cut->>'to')<>1 then
      raise exception 'evidence_projection_proof_reverse_cut_not_unique: %',cut->>'name';end if;
    original:=replace(original,cut->>'to',cut->>'from');
  end loop;
  if encode(sha256(convert_to(original,'UTF8')),'hex') is distinct from spec->'target'->>'sha' then
    raise exception 'evidence_projection_proof_inverse_changed';end if;
  rebuilt:=original;
  for cut in select value from jsonb_array_elements(spec->'cuts') loop
    if (length(rebuilt)-length(replace(rebuilt,cut->>'from','')))/length(cut->>'from')<>1 then
      raise exception 'evidence_projection_proof_forward_cut_not_unique: %',cut->>'name';end if;
    rebuilt:=replace(rebuilt,cut->>'from',cut->>'to');
  end loop;
  if rebuilt is distinct from installed
    or (length(installed)-length(replace(installed,'bx1_private.offering_signature_evidence_current(op.id)','')))
      /length('bx1_private.offering_signature_evidence_current(op.id)')<>1 then
    raise exception 'evidence_projection_proof_single_evaluation_or_rebuild_changed';end if;
  for dependency in select value from jsonb_array_elements(spec->'dependencies') loop
    select to_jsonb(p) into metadata from pg_catalog.pg_proc p where p.oid=(dependency->>'oid')::oid;
    if metadata is null or metadata-'prosrc' is distinct from dependency->'metadata'
      or encode(sha256(convert_to(metadata->>'prosrc','UTF8')),'hex') is distinct from dependency->>'sha' then
      raise exception 'evidence_projection_proof_dependency_changed: %',dependency->>'oid';end if;
  end loop;
  select jsonb_build_object(
      'constraints',(select coalesce(jsonb_agg(to_jsonb(c) order by c.oid),'[]'::jsonb)
        from pg_catalog.pg_constraint c where c.conrelid in ('bx1_private.offering_document_profiles'::regclass,
          'bx1_private.offering_document_manifests'::regclass) and c.contype in ('p','u')),
      'indexes',(select coalesce(jsonb_agg(to_jsonb(i) order by i.indexrelid),'[]'::jsonb)
        from pg_catalog.pg_index i where i.indexrelid in (29736,29738,29957,29959)),
      'columns',(select coalesce(jsonb_agg(to_jsonb(a) order by a.attrelid,a.attnum),'[]'::jsonb)
        from pg_catalog.pg_attribute a where a.attrelid in ('bx1_private.offering_document_profiles'::regclass,
          'bx1_private.offering_document_manifests'::regclass) and a.attname='offering_revision_id')) into actual_relations;
  if actual_relations is distinct from spec->'relations' then
    raise exception 'evidence_projection_proof_cardinality_changed';end if;

  -- Extract both actual CASE/approval expressions; substitute only the expensive
  -- subquery inputs with typed, ephemeral booleans. Existing EXISTS remains
  -- two-valued: false/unknown current evidence cannot become approval.
  old_status:=split_part(split_part(original,'''signature_status'',',2),E',\n    ''approval_allowed'',',1);
  new_status:=split_part(split_part(installed,'''signature_status'',',2),E',\n    ''approval_allowed'',',1);
  old_approval:=split_part(split_part(original,'''approval_allowed'',',2),') end',1);
  new_approval:=split_part(split_part(installed,'''approval_allowed'',',2),') end',1);
  materialized_sql:=left(installed,strpos(installed,E'\n  select case')-1);
  if old_status='' or new_status='' or old_approval='' or new_approval='' or materialized_sql='' then
    raise exception 'evidence_projection_proof_actual_expressions_missing';end if;
  for substitution in select value from jsonb_array_elements(spec->'substitutions') loop
    old_status:=replace(old_status,substitution->>'from',substitution->>'to');
    new_status:=replace(new_status,substitution->>'from',substitution->>'to');
    old_approval:=replace(old_approval,substitution->>'from',substitution->>'to');
    new_approval:=replace(new_approval,substitution->>'from',substitution->>'to');
    materialized_sql:=replace(materialized_sql,substitution->>'from',substitution->>'to');
  end loop;
  materialized_sql:=replace(materialized_sql,E'\n  with retained_evidence',', retained_evidence');
  materialized_sql:=replace(materialized_sql,'evidence_profile.offering_revision_id=target_revision',
    'evidence_profile.offering_revision_id=(select inputs.target_revision from inputs)');
  materialized_sql:=replace(materialized_sql,'bx1_private.offering_document_profiles evidence_profile',
    '(select inputs.target_revision as offering_revision_id from inputs where inputs.profile_present is true) evidence_profile');
  proof_query:='with inputs as (select $1::boolean profile_present,$2::boolean admitted_current,$3::boolean retained_current,'
    ||'$4::boolean recovery_exists,$5::boolean noncurrent_exists,$6::boolean pending_exists,$7::boolean purpose_exists,'
    ||'''11111111-1111-4111-8111-111111111111''::uuid target_revision)'
    ||materialized_sql||' select case when inputs.profile_present is true then jsonb_build_object('
    ||'''signature_status'','||old_status||',''approval_allowed'','||old_approval||') else null::jsonb end,'
    ||'case when inputs.profile_present is true then jsonb_build_object('
    ||'''signature_status'','||new_status||',''approval_allowed'','||new_approval||') else null::jsonb end,'
    ||'(select count(*) from retained_evidence) from inputs';
  if proof_query like '%bx1_%' or proof_query like '%auth.%' then
    raise exception 'evidence_projection_proof_unreplaced_native_dependency';end if;
  for profile_present in select value from (values(false),(true),(null::boolean)) input(value) loop
    for admitted_current in select value from (values(false),(true),(null::boolean)) input(value) loop
      for retained_current in select value from (values(false),(true),(null::boolean)) input(value) loop
        for flags in 0..15 loop
          execute proof_query into old_result,new_result,gated_rows using profile_present,admitted_current,retained_current,
            (flags&1)<>0,(flags&2)<>0,(flags&4)<>0,(flags&8)<>0;
          if old_result is distinct from new_result or gated_rows is distinct from (case when profile_present is true then 1 else 0 end)::bigint then
            raise exception 'evidence_projection_proof_field_or_profile_gate_mismatch';end if;
          if profile_present is not true and new_result is not null then
            raise exception 'evidence_projection_proof_missing_profile_must_be_null';end if;
          if retained_current is not true and new_result->'approval_allowed' is distinct from
              (case when profile_present is true then 'false'::jsonb else null::jsonb end) then
            raise exception 'evidence_projection_proof_false_or_unknown_must_not_approve';end if;
          cases:=cases+1;
        end loop;
      end loop;
    end loop;
  end loop;
  if cases<>432 then raise exception 'evidence_projection_proof_cases_missing';end if;

  -- The initial materialized value is never passed to the later reader. Extract
  -- its unchanged fresh full-package comparison and prove withdrawal is denied.
  select p.prosrc into reader_body from pg_catalog.pg_proc p where p.oid=30335;
  fresh_fence:=spec->>'finalFence';
  if strpos(reader_body,fresh_fence)=0 then raise exception 'evidence_projection_proof_fresh_fence_missing';end if;
  fresh_fence:=replace(fresh_fence,'bx1_portal.offering_workflow_package_projection(c,(value->>''id'')::uuid)','$1::jsonb');
  fresh_fence:=replace(fresh_fence,'value->''offering_package''','$2::jsonb');
  if fresh_fence like '%bx1_%' then raise exception 'evidence_projection_proof_fresh_native_call_remaining';end if;
  for phase_case in select value from jsonb_array_elements($evidence_projection_fresh_cases$[
    {"initial":{"signature_status":"EVIDENCE_RETAINED","approval_allowed":true},"final":{"signature_status":"EVIDENCE_RETAINED","approval_allowed":true},"denied":false},
    {"initial":{"signature_status":"EVIDENCE_RETAINED","approval_allowed":true},"final":{"signature_status":"NON_CURRENT","approval_allowed":false},"denied":true},
    {"initial":{"signature_status":"EVIDENCE_RETAINED","approval_allowed":true},"denied":true}
  ]$evidence_projection_fresh_cases$::jsonb) loop
    execute 'select '||fresh_fence into changed using phase_case->'final',phase_case->'initial';
    if changed is distinct from (phase_case->>'denied')::boolean then
      raise exception 'evidence_projection_proof_late_withdrawal_not_denied';end if;
  end loop;
  if pg_catalog.current_setting('request.jwt.claims',true) is distinct from claims_before
    or pg_catalog.current_setting('request.jwt.claim.sub',true) is distinct from sub_before or auth.uid() is not null then
    raise exception 'evidence_projection_proof_claims_changed';end if;
end $evidence_projection_read_proof$;
